"""External isolated OSQP feasibility solve. Local files only; Blender ABI independent."""
import sys,json,numpy as np,scipy.sparse as sp,osqp
from pathlib import Path
inp=Path(sys.argv[1]);out=Path(sys.argv[2]);d=np.load(inp);n=int(d['n']);A=sp.csc_matrix((d['A_data'],(d['A_rows'],d['A_cols'])),shape=(len(d['lower']),n));L=sp.csc_matrix((d['L_data'],(d['L_rows'],d['L_cols'])),shape=(int(d['L_nrows']),n));P=2*(L.T@L+.005*sp.eye(n,format='csc'));solver=osqp.OSQP();solver.setup(P=sp.triu(P,format='csc'),q=np.zeros(n),A=A,l=d['lower'],u=d['upper'],eps_abs=1e-7,eps_rel=1e-7,max_iter=30000,polishing=True,verbose=False,scaled_termination=True,time_limit=30)
if 'warm' in d and len(d['warm'])==n:solver.warm_start(x=d['warm'])
r=solver.solve();np.savez(out,x=r.x if r.x is not None else np.zeros(n),primal_infeasibility_certificate=r.prim_inf_cert if r.prim_inf_cert is not None else np.array([]));info={'status':r.info.status,'status_val':r.info.status_val,'iterations':r.info.iter,'objective':r.info.obj_val,'primal_residual':r.info.prim_res,'dual_residual':r.info.dual_res,'run_time':r.info.run_time,'osqp_version':osqp.__version__};out.with_suffix('.json').write_text(json.dumps(info,indent=2)+'\n');print(json.dumps(info))
